// NAVIGATION MENU JS
let menuIcon = $(".toggle-nav");
let nav = $(".nav");
let navItem = $(".nav__item");

menuIcon.click(function () {
  $(this).toggleClass("toggle-nav--open");

  if (nav.hasClass("nav--open")) {
    navItem.removeClass("nav__item--open");

    setTimeout(function () {
      nav.removeClass("nav--open");
    }, 550);
  } else {
    nav.addClass("nav--open");

    setTimeout(function () {
      navItem.addClass("nav__item--open");
    }, 550);
  }
});

// SOCIAL PANEL JS
const floating_btn = document.querySelector(".floating-btn");
const close_btn = document.querySelector(".close-btn");
const social_panel_container = document.querySelector(
  ".social-panel-container"
);

floating_btn.addEventListener("click", () => {
  social_panel_container.classList.toggle("visible");
});

close_btn.addEventListener("click", () => {
  social_panel_container.classList.remove("visible");
});

// WEBIPTV JS
document.addEventListener("DOMContentLoaded", () => {
  const playerPanel = document.getElementById("playerPanel");
  const backButton = document.getElementById("backButton");
  const nowPlaying = document.getElementById("nowPlaying");
  const categorySelect = document.getElementById("categorySelect");
  const channelGrid = document.getElementById("channelGrid");
  const gridViewButton = document.getElementById("gridViewButton");
  const listViewButton = document.getElementById("listViewButton");
  let currentView = "grid";
  let selectedChannelUrl = "";
  const m3uLinkInput = document.getElementById("m3uLink");
  const loadButton = document.getElementById("loadButton");
  const uploadFile = document.getElementById("uploadFile");
  const videoSection = document.getElementById("videoSection");
  let channels = [];
  let videojsPlayer = null;

  function loadChannels(data) {
    const lines = data.split(/\r?\n/);
    let currentChannel = {};
    let currentCategory = "";
    lines.forEach((rawLine) => {
      const line = rawLine.trim();
      if (line.startsWith("#EXTGRP:")) {
        currentCategory = line.substring(8).trim();
      } else if (line.startsWith("#EXTINF:")) {
        const lastCommaIndex = line.lastIndexOf(",");
        currentChannel.name = line.slice(lastCommaIndex + 1).trim();
        const groupTitleMatch = line.match(/group-title="([^"]*)"/);
        const logoMatch = line.match(/tvg-logo="([^"]*)"/);

        currentChannel.category = groupTitleMatch
          ? groupTitleMatch[1]
          : currentCategory || "Unknown";
        currentChannel.logo = logoMatch ? logoMatch[1] : "";
      } else if (line.startsWith("http://") || line.startsWith("https://")) {
        currentChannel.url = line;
        channels.push(currentChannel);
        currentChannel = {};
      }
    });

    gridViewButton.addEventListener("click", () => {
      currentView = "grid";
      channelGrid.classList.remove("list-view");
      channelGrid.classList.add("grid-view");
      gridViewButton.classList.remove("btn-outline-light");
      gridViewButton.classList.add("btn-primary");
      listViewButton.classList.remove("btn-primary");
      listViewButton.classList.add("btn-outline-light");
    });

    listViewButton.addEventListener("click", () => {
      currentView = "list";
      channelGrid.classList.remove("grid-view");
      channelGrid.classList.add("list-view");
      listViewButton.classList.remove("btn-outline-light");
      listViewButton.classList.add("btn-primary");
      gridViewButton.classList.remove("btn-primary");
      gridViewButton.classList.add("btn-outline-light");
    });

    const categories = [
      ...new Set(channels.map((channel) => channel.category))
    ];
    categories.forEach((category) => {
      const option = document.createElement("option");
      option.text = category;
      option.value = category;
      categorySelect.appendChild(option);
    });

    function renderChannels(filteredChannels) {
      channelGrid.innerHTML = "";
      filteredChannels.forEach((channel) => {
        const card = document.createElement("button");
        card.type = "button";
        card.className = "channel-card";
        if (channel.url === selectedChannelUrl) {
          card.classList.add("active");
        }

     // Used corsproxy images if url index of http protocol
    let getProxyImg = "https://images.weserv.nl";
    function getSecureImg(url, corsProxy = getProxyImg) {
      try {
        const parsed = new URL(url);
        if (parsed.protocol === "https:") {
          return url;
        } else if (parsed.protocol === "http:") {
          const proxy = corsProxy.endsWith("/?url=") ? corsProxy : corsProxy + "/?url=";
          return proxy + url;
        }
        return url;
      } catch (e) {
        return url;
      }
    }
       
        const safeLogo =
          channel.logo ||
          "https://static.wixstatic.com/media/decb9b_408149b290cf44229f7c308a82161597~mv2.png";
        card.innerHTML = `
      ${
        channel.url === selectedChannelUrl
          ? '<span class="channel-playing">🔴 LIVE</span>'
          : ""
      }

      <img
        src="${getSecureImg(safeLogo)}" loading="lazy"
        alt="${channel.name || "Channel"} logo"
        onerror="this.style.display='none'"
      >

      <span class="channel-card-info">
        <span class="channel-card-name">
          ${channel.name || "Unnamed channel"}
        </span>
        <span class="channel-card-category">
          ${channel.category || "Unknown"}
        </span>
      </span>
    `;

        card.addEventListener("click", () => {
          openPlayer(channel);
          renderChannels(filteredChannels);
        });

        channelGrid.appendChild(card);
      });
    }

    function playFirstChannelInCategory(category) {
      const filteredChannels = channels.filter(
        (channel) => channel.category === category
      );

      if (filteredChannels.length === 0) {
        selectedChannelUrl = "";
        renderChannels([]);
        return;
      }

      // Select/highlight the first channel only.
      // Do not start the player automatically.
      selectedChannelUrl = filteredChannels[0].url;

      renderChannels(filteredChannels);
    }

    categorySelect.addEventListener("change", () => {
      const selectedCategory = categorySelect.value;

      // Close the current player when changing category
      closePlayer();

      // Select the first channel visually, but do not play it
      playFirstChannelInCategory(selectedCategory);
    });

    renderChannels([]);
    if (categories.length > 0) {
      const firstCategory = categories[0];
      categorySelect.value = firstCategory;

      playFirstChannelInCategory(firstCategory);
    }
  }

  function recreateVideoTagIfNeeded() {
    // If #player doesn't exist, create and append it
    if (!document.getElementById("player")) {
      const videoTag = document.createElement("video");
      videoTag.id = "player";
      videoTag.className = "video-js";
      videoTag.setAttribute("autoplay", "");
      videoTag.setAttribute("muted", "");
      videoTag.setAttribute("controls", "");
      videoTag.setAttribute("playsinline", "");
      videoTag.setAttribute("crossorigin", "");
      videoSection.appendChild(videoTag);
    }
  }

  function playStream(url) {
    if (videojsPlayer) {
      videojsPlayer.dispose();
      videojsPlayer = null;
    }
    // Re-create the video element if needed
    recreateVideoTagIfNeeded();
    // Always use the latest video element
    const playerElement = document.getElementById("player");
    // Create new Video.js player instance
    videojsPlayer = videojs(playerElement, {
      html5: {
        vhs: {
          overrideNative: true
        },
        nativeAudioTracks: false,
        nativeVideoTracks: false
      },
      autoplay: true,
      controls: true,
      liveui: true,
      muted: true,
      playsinline: true,
      preload: "auto"
    });

    // Used corsproxy if url index of http protocol
    let getProxyUrl = "https://seep.eu.org";
    function getSecureUrl(url, corsProxy = getProxyUrl) {
      try {
        const parsed = new URL(url);
        if (parsed.protocol === "https:") {
          return url;
        } else if (parsed.protocol === "http:") {
          const proxy = corsProxy.endsWith("/") ? corsProxy : corsProxy + "/";
          return proxy + url;
        }
        return url;
      } catch (e) {
        return url;
      }
    }

    const sURL = getSecureUrl(url);
    // Set video source based on extension
    if (url.indexOf(".ts") > 0) {
      videojsPlayer.src({
        src: sURL,
        type: "video/mp2t"
      });
    } else if (url.indexOf("ts") > 0) {
      videojsPlayer.src({
        src: sURL,
        type: "video/mp2t"
      });
    } else if (url.indexOf(".m3u8") > 0) {
      videojsPlayer.src({
        type: "application/x-mpegURL",
        src: sURL
      });
    } else if (url.indexOf("m3u8") > 0) {
      videojsPlayer.src({
        type: "application/x-mpegURL",
        src: sURL
      });
      // Add the quality menu button
      videojsPlayer.qualityMenu();
    } else if (url.indexOf(".mpd") > 0) {
      videojsPlayer.src({
        type: "application/dash+xml",
        src: sURL
      });
      // Add the quality menu button
    } else if (url.indexOf(".mp4") > 0) {
      videojsPlayer.src({
        type: "video/mp4",
        src: sURL
      });
      // Add the quality menu button
      videojsPlayer.qualityMenu();
    } else {
      videojsPlayer.src({
        src: sURL
      });
    }
    videojsPlayer.load();
    videojsPlayer.play().catch(() => {
      console.log("Playback requires user interaction.");
    });
  }

  function openPlayer(channel) {
    selectedChannelUrl = channel.url;
    nowPlaying.textContent = `Now playing: ${channel.name}`;

    playerPanel.classList.add("is-open");

    playStream(channel.url);
  }

  function closePlayer() {
    if (videojsPlayer) {
      videojsPlayer.pause();
      videojsPlayer.dispose();
      videojsPlayer = null;
    }

    playerPanel.classList.remove("is-open");
    nowPlaying.textContent = "";
  }
  backButton.addEventListener("click", closePlayer);

  async function enterBrowserFullscreen() {
    if (playerPanel.requestFullscreen) {
      await playerPanel.requestFullscreen();
    }
  }

  loadButton.addEventListener("click", () => {
    const m3uUrl = m3uLinkInput.value;
    if (m3uUrl) {
      channels = [];
      categorySelect.innerHTML = "";
      channelGrid.innerHTML = "";
      fetch(m3uUrl)
        .then((response) => response.text())
        .then((data) => {
          loadChannels(data);
        })
        .catch((error) => {
          console.error("Error:", error);
        });
    } else {
      console.log("Please enter an M3U link.");
    }
  });

  uploadFile.addEventListener("change", (event) => {
    const file = event.target.files[0];
    if (file) {
      channels = [];
      categorySelect.innerHTML = "";
      channelGrid.innerHTML = "";
      const reader = new FileReader();
      reader.onload = function (e) {
        const fileContent = e.target.result;
        loadChannels(fileContent);
      };
      reader.readAsText(file);
    }
  });

  window.onload = () => {
    // playlist by category
    const placeholderM3ULink =
      "https://iptv-org.github.io/iptv/index.category.m3u";
    if (placeholderM3ULink) {
      channels = [];
      categorySelect.innerHTML = "";
      channelGrid.innerHTML = "";
      fetch(placeholderM3ULink)
        .then((response) => response.text())
        .then((data) => {
          loadChannels(data);
        })
        .catch((error) => {
          console.error("Error:", error);
        });
    }
  };
});
